import "./Admin.css";
import { useEffect, useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "../AuthContext";

function Admin() {
  const [inquiries, setInquiries] = useState([]);
  const [search, setSearch] = useState("");
  const navigate = useNavigate();
  const { isAuthenticated } = useContext(AuthContext); // check authentication

  useEffect(() => {
    if (!isAuthenticated) {
      navigate("/login"); // redirect if not logged in
    }
  }, [isAuthenticated, navigate]);

  const fetchInquiries = async () => {
    try {
      const response = await fetch("http://127.0.0.1:8000/inquiries");
      const data = await response.json();
      setInquiries(data);
    } catch (error) {
      console.error("Error fetching inquiries:", error);
    }
  };

  const deleteInquiry = async (id) => {
    try {
      const response = await fetch(`http://127.0.0.1:8000/inquiry/${id}`, {
        method: "DELETE",
      });
      if (response.ok) {
        alert("Inquiry deleted successfully!");
        fetchInquiries();
      } else {
        const err = await response.json();
        alert(err.detail);
      }
    } catch (error) {
      console.error("Error deleting inquiry:", error);
    }
  };

  useEffect(() => {
    fetchInquiries();
  }, []);

  // Filter inquiries
  const filteredInquiries = inquiries.filter(
    (inq) =>
      inq.name.toLowerCase().includes(search.toLowerCase()) ||
      inq.mobile.includes(search)
  );

  return (
    <div>
      <h1>Admin Panel - Inquiries</h1>
      <input
        type="text"
        placeholder="Search by name or mobile..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        style={{ marginBottom: "15px", padding: "5px", width: "250px" }}
      />

      {filteredInquiries.length === 0 ? (
        <p>No inquiries found.</p>
      ) : (
        <table border="1" cellPadding="10">
          <thead>
            <tr>
              <th>Name</th>
              <th>Email</th>
              <th>Mobile</th>
              <th>Message</th>
              <th>Date</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {filteredInquiries.map((inq) => (
              <tr key={inq._id}>
                <td>{inq.name}</td>
                <td>{inq.email}</td>
                <td>{inq.mobile}</td>
                <td>{inq.message}</td>
                <td>{new Date(inq.date).toLocaleString()}</td>
                <td>
                  <button onClick={() => deleteInquiry(inq._id)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default Admin;
